14	package io.reactivex.rxjava4.internal.operators.observable;
15	
16	import io.reactivex.rxjava4.core.*;
17	import io.reactivex.rxjava4.exceptions.Exceptions;
18	import io.reactivex.rxjava4.functions.Supplier;
19	import io.reactivex.rxjava4.internal.disposables.EmptyDisposable;
20	
21	import java.util.Objects;
22	
23	public final class ObservableDefer<T> extends Observable<T> {
24	    final Supplier<? extends ObservableSource<? extends T>> supplier;
25	    public ObservableDefer(Supplier<? extends ObservableSource<? extends T>> supplier) {
26	        this.supplier = supplier;
27	    }
28	
29	    @Override
30	    public void subscribeActual(Observer<? super T> observer) {
31	        ObservableSource<? extends T> pub;
32	        try {
33	            pub = Objects.requireNonNull(supplier.get(), "The supplier returned a null ObservableSource");
34	        } catch (Throwable t) {
35	            Exceptions.throwIfFatal(t);
36	            EmptyDisposable.error(t, observer);
37	            return;
38	        }
39	
40	        pub.subscribe(observer);
41	    }
42	}
