19	import io.reactivex.rxjava4.internal.disposables.EmptyDisposable;
20	import io.reactivex.rxjava4.internal.util.ExceptionHelper;
21	
22	public final class ObservableError<T> extends Observable<T> {
23	    final Supplier<? extends Throwable> errorSupplier;
24	    public ObservableError(Supplier<? extends Throwable> errorSupplier) {
25	        this.errorSupplier = errorSupplier;
26	    }
27	
28	    @Override
29	    public void subscribeActual(Observer<? super T> observer) {
30	        Throwable error;
31	        try {
32	            error = ExceptionHelper.nullCheck(errorSupplier.get(), "Supplier returned a null Throwable.");
33	        } catch (Throwable t) {
34	            Exceptions.throwIfFatal(t);
35	            error = t;
36	        }
37	        EmptyDisposable.error(error, observer);
38	    }
