16	import static java.util.concurrent.Flow.*;
17	
18	import io.reactivex.rxjava4.core.*;
19	import io.reactivex.rxjava4.internal.subscriptions.*;
20	
21	import java.io.Serial;
22	
23	public final class FlowableCount<T> extends AbstractFlowableWithUpstream<T, Long> {
24	
25	    public FlowableCount(Flowable<T> source) {
26	        super(source);
27	    }
28	
29	    @Override
30	    protected void subscribeActual(Subscriber<? super Long> s) {
31	        source.subscribe(new CountSubscriber(s));
32	    }
33	
34	    static final class CountSubscriber extends DeferredScalarSubscription<Long>
35	    implements FlowableSubscriber<Object> {
36	
37	        @Serial
38	        private static final long serialVersionUID = 4973004223787171406L;
39	
40	        Subscription upstream;
41	
42	        long count;
43	
44	        CountSubscriber(Subscriber<? super Long> downstream) {
45	            super(downstream);
46	        }
47	
48	        @Override
49	        public void onSubscribe(Subscription s) {
50	            if (SubscriptionHelper.validate(this.upstream, s)) {
51	                this.upstream = s;
52	                downstream.onSubscribe(this);
53	                s.request(Long.MAX_VALUE);
54	            }
55	        }
56	
57	        @Override
58	        public void onNext(Object t) {
59	            count++;
60	        }
61	
62	        @Override
63	        public void onError(Throwable t) {
64	            downstream.onError(t);
65	        }
66	
67	        @Override
68	        public void onComplete() {
69	            complete(count);
70	        }
71	
72	        @Override
73	        public void cancel() {
74	            super.cancel();
75	            upstream.cancel();
76	        }
77	    }
78	}
