14	package io.reactivex.rxjava4.internal.operators.flowable;
15	
16	import static java.util.concurrent.Flow.*;
17	
18	import io.reactivex.rxjava4.annotations.Nullable;
19	import io.reactivex.rxjava4.core.Flowable;
20	import io.reactivex.rxjava4.functions.Predicate;
21	import io.reactivex.rxjava4.internal.subscribers.*;
22	import io.reactivex.rxjava4.operators.ConditionalSubscriber;
23	import io.reactivex.rxjava4.operators.QueueSubscription;
24	
25	public final class FlowableFilter<T> extends AbstractFlowableWithUpstream<T, T> {
26	    final Predicate<? super T> predicate;
27	    public FlowableFilter(Flowable<T> source, Predicate<? super T> predicate) {
28	        super(source);
29	        this.predicate = predicate;
30	    }
31	
32	    @Override
33	    protected void subscribeActual(Subscriber<? super T> s) {
34	        if (s instanceof ConditionalSubscriber) {
35	            source.subscribe(new FilterConditionalSubscriber<>(
36	                    (ConditionalSubscriber<? super T>) s, predicate));
37	        } else {
38	            source.subscribe(new FilterSubscriber<>(s, predicate));
39	        }
40	    }
41	
42	    static final class FilterSubscriber<T> extends BasicFuseableSubscriber<T, T>
43	    implements ConditionalSubscriber<T> {
44	        final Predicate<? super T> filter;
45	
46	        FilterSubscriber(Subscriber<? super T> actual, Predicate<? super T> filter) {
47	            super(actual);
48	            this.filter = filter;
49	        }
50	
51	        @Override
52	        public void onNext(T t) {
53	            if (!tryOnNext(t)) {
54	                upstream.request(1);
55	            }
56	        }
57	
58	        @Override
59	        public boolean tryOnNext(T t) {
60	            if (done) {
61	                return false;
62	            }
63	            if (sourceMode != NONE) {
64	                downstream.onNext(null);
65	                return true;
66	            }
67	            boolean b;
68	            try {
69	                b = filter.test(t);
70	            } catch (Throwable e) {
71	                fail(e);
72	                return true;
73	            }
74	            if (b) {
75	                downstream.onNext(t);
76	            }
77	            return b;
78	        }
79	
80	        @Override
81	        public int requestFusion(int mode) {
82	            return transitiveBoundaryFusion(mode);
83	        }
84	
85	        @Nullable
86	        @Override
87	        public T poll() throws Throwable {
88	            QueueSubscription<T> qs = this.qs;
89	            Predicate<? super T> f = filter;
90	
91	            for (;;) {
92	                T t = qs.poll();
93	                if (t == null) {
94	                    return null;
95	                }
96	
97	                if (f.test(t)) {
98	                    return t;
99	                }
100	
101	                if (sourceMode == ASYNC) {
102	                    qs.request(1);
103	                }
104	            }
105	        }
106	    }
107	
108	    static final class FilterConditionalSubscriber<T> extends BasicFuseableConditionalSubscriber<T, T> {
109	        final Predicate<? super T> filter;
110	
111	        FilterConditionalSubscriber(ConditionalSubscriber<? super T> actual, Predicate<? super T> filter) {
112	            super(actual);
113	            this.filter = filter;
114	        }
115	
116	        @Override
117	        public void onNext(T t) {
118	            if (!tryOnNext(t)) {
119	                upstream.request(1);
120	            }
121	        }
122	
123	        @Override
124	        public boolean tryOnNext(T t) {
125	            if (done) {
126	                return false;
127	            }
128	
129	            if (sourceMode != NONE) {
130	                return downstream.tryOnNext(null);
131	            }
132	
133	            boolean b;
134	            try {
135	                b = filter.test(t);
136	            } catch (Throwable e) {
137	                fail(e);
138	                return true;
139	            }
140	            return b && downstream.tryOnNext(t);
141	        }
142	
143	        @Override
144	        public int requestFusion(int mode) {
145	            return transitiveBoundaryFusion(mode);
146	        }
147	
148	        @Nullable
149	        @Override
150	        public T poll() throws Throwable {
151	            QueueSubscription<T> qs = this.qs;
152	            Predicate<? super T> f = filter;
153	
154	            for (;;) {
155	                T t = qs.poll();
156	                if (t == null) {
157	                    return null;
158	                }
159	
160	                if (f.test(t)) {
161	                    return t;
162	                }
163	
164	                if (sourceMode == ASYNC) {
165	                    qs.request(1);
166	                }
167	            }
168	        }
169	    }
170	}
