27	/**
28	 * Utility class to help with the queue-drain serialization idiom.
29	 */
30	public final class QueueDrainHelper {
31	    /** Utility class. */
32	    private QueueDrainHelper() {
33	        throw new IllegalStateException("No instances!");
34	    }
35	
36	    /**
37	     * Drain the queue but give up with an error if there aren't enough requests.
38	     * @param <T> the queue value type
39	     * @param <U> the emission value type
40	     * @param q the queue
41	     * @param subscriber the subscriber
42	     * @param delayError true if errors should be delayed after all normal items
43	     * @param dispose the disposable to call when termination happens and cleanup is necessary
44	     * @param qd the QueueDrain instance that gives status information to the drain logic
45	     */
46	    public static <T, U> void drainMaxLoop(SimplePlainQueue<T> q, Subscriber<? super U> subscriber, boolean delayError,
47	            Disposable dispose, QueueDrain<T, U> qd) {
48	        int missed = 1;
49	
50	        for (;;) {
51	            for (;;) {
52	                boolean d = qd.done();
53	
54	                T v = q.poll();
55	
56	                boolean empty = v == null;
57	
58	                if (checkTerminated(d, empty, subscriber, delayError, q, qd)) {
59	                    if (dispose != null) {
60	                        dispose.dispose();
61	                    }
62	                    return;
63	                }
64	
65	                if (empty) {
66	                    break;
67	                }
68	
69	                long r = qd.requested();
70	                if (r != 0L) {
71	                    if (qd.accept(subscriber, v)) {
72	                        if (r != Long.MAX_VALUE) {
73	                            qd.produced(1);
74	                        }
75	                    }
76	                } else {
77	                    q.clear();
78	                    if (dispose != null) {
79	                        dispose.dispose();
80	                    }
81	                    subscriber.onError(MissingBackpressureException.createDefault());
82	                    return;
83	                }
84	            }
85	
86	            missed = qd.leave(-missed);
87	            if (missed == 0) {
88	                break;
89	            }
90	        }
91	    }
92	
93	    public static <T, U> boolean checkTerminated(boolean d, boolean empty,
94	            Subscriber<?> s, boolean delayError, SimpleQueue<?> q, QueueDrain<T, U> qd) {
95	        if (qd.cancelled()) {
96	            q.clear();
97	            return true;
98	        }
99	
100	        if (d) {
101	            if (delayError) {
102	                if (empty) {
103	                    Throwable err = qd.error();
104	                    if (err != null) {
105	                        s.onError(err);
106	                    } else {
107	                        s.onComplete();
108	                    }
109	                    return true;
110	                }
111	            } else {
112	                Throwable err = qd.error();
113	                if (err != null) {
114	                    q.clear();
115	                    s.onError(err);
116	                    return true;
117	                } else
118	                if (empty) {
119	                    s.onComplete();
120	                    return true;
121	                }
122	            }
123	        }
124	
125	        return false;
126	    }
127	
128	    public static <T, U> void drainLoop(SimplePlainQueue<T> q, Observer<? super U> a, boolean delayError, Disposable dispose, ObservableQueueDrain<T, U> qd) {
129	
130	        int missed = 1;
131	
132	        for (;;) {
133	            if (checkTerminated(qd.done(), q.isEmpty(), a, delayError, q, dispose, qd)) {
134	                return;
135	            }
136	
137	            for (;;) {
138	                boolean d = qd.done();
139	                T v = q.poll();
140	                boolean empty = v == null;
141	
142	                if (checkTerminated(d, empty, a, delayError, q, dispose, qd)) {
143	                    return;
144	                }
145	
146	                if (empty) {
147	                    break;
148	                }
149	
150	                qd.accept(a, v);
151	            }
152	
153	            missed = qd.leave(-missed);
154	            if (missed == 0) {
155	                break;
156	            }
157	        }
158	    }
159	
160	    public static <T, U> boolean checkTerminated(boolean d, boolean empty,
161	            Observer<?> observer, boolean delayError, SimpleQueue<?> q, Disposable disposable, ObservableQueueDrain<T, U> qd) {
162	        if (qd.cancelled()) {
163	            q.clear();
164	            disposable.dispose();
165	            return true;
166	        }
167	
168	        if (d) {
169	            if (delayError) {
170	                if (empty) {
171	                    if (disposable != null) {
172	                        disposable.dispose();
173	                    }
174	                    Throwable err = qd.error();
175	                    if (err != null) {
176	                        observer.onError(err);
177	                    } else {
178	                        observer.onComplete();
179	                    }
180	                    return true;
181	                }
182	            } else {
183	                Throwable err = qd.error();
184	                if (err != null) {
185	                    q.clear();
186	                    if (disposable != null) {
187	                        disposable.dispose();
188	                    }
189	                    observer.onError(err);
190	                    return true;
191	                } else
192	                if (empty) {
193	                    if (disposable != null) {
194	                        disposable.dispose();
195	                    }
196	                    observer.onComplete();
197	                    return true;
198	                }
199	            }
200	        }
201	
202	        return false;
203	    }
204	
205	    /**
206	     * Creates a queue: spsc-array if capacityHint is positive and
207	     * spsc-linked-array if capacityHint is negative; in both cases, the
208	     * capacity is the absolute value of prefetch.
209	     * @param <T> the value type of the queue
210	     * @param capacityHint the capacity hint, negative value will create an array-based SPSC queue
211	     * @return the queue instance
212	     */
213	    public static <T> SimpleQueue<T> createQueue(int capacityHint) {
214	        if (capacityHint < 0) {
215	            return new SpscLinkedArrayQueue<>(-capacityHint);
216	        }
217	        return new SpscArrayQueue<>(capacityHint);
218	    }
219	
220	    /**
221	     * Requests {@link Long#MAX_VALUE} if prefetch is negative or the exact
222	     * amount if prefetch is positive.
223	     * @param s the Subscription to request from
224	     * @param prefetch the prefetch value
225	     */
226	    public static void request(Subscription s, int prefetch) {
227	        s.request(prefetch < 0 ? Long.MAX_VALUE : prefetch);
228	    }
