230	    static final long COMPLETED_MASK = 0x8000000000000000L;
231	    static final long REQUESTED_MASK = 0x7FFFFFFFFFFFFFFFL;
232	
233	    /**
234	     * Accumulates requests (not validated) and handles the completed mode draining of the queue based on the requests.
235	     *
236	     * <p>
237	     * Post-completion backpressure handles the case when a source produces values based on
238	     * requests when it is active but more values are available even after its completion.
239	     * In this case, the onComplete() can't just emit the contents of the queue but has to
240	     * coordinate with the requested amounts. This requires two distinct modes: active and
241	     * completed. In active mode, requests flow through and the queue is not accessed but
242	     * in completed mode, requests no-longer reach the upstream but help in draining the queue.
243	     *
244	     * @param <T> the value type emitted
245	     * @param n the request amount, positive (not validated)
246	     * @param actual the target Subscriber to send events to
247	     * @param queue the queue to drain if in the post-complete state
248	     * @param state holds the request amount and the post-completed flag
249	     * @param isCancelled a supplier that returns true if the drain has been cancelled
250	     * @return true if the state indicates a completion state.
251	     */
252	    public static <T> boolean postCompleteRequest(long n,
253	                                                  Subscriber<? super T> actual,
254	                                                  Queue<T> queue,
255	                                                  AtomicLong state,
256	                                                  BooleanSupplier isCancelled) {
257	        for (; ; ) {
258	            long r = state.get();
259	
260	            // extract the current request amount
261	            long r0 = r & REQUESTED_MASK;
262	
263	            // preserve COMPLETED_MASK and calculate new requested amount
264	            long u = (r & COMPLETED_MASK) | BackpressureHelper.addCap(r0, n);
265	
266	            if (state.compareAndSet(r, u)) {
267	                // (complete, 0) -> (complete, n) transition then replay
268	                if (r == COMPLETED_MASK) {
269	
270	                    postCompleteDrain(n | COMPLETED_MASK, actual, queue, state, isCancelled);
271	
272	                    return true;
273	                }
274	                // (active, r) -> (active, r + n) transition then continue with requesting from upstream
275	                return false;
276	            }
277	        }
278	
279	    }
280	
281	    static boolean isCancelled(BooleanSupplier cancelled) {
282	        try {
283	            return cancelled.getAsBoolean();
284	        } catch (Throwable ex) {
285	            Exceptions.throwIfFatal(ex);
286	            return true;
287	        }
288	    }
289	
290	    /**
291	     * Drains the queue based on the outstanding requests in post-completed mode (only!).
292	     *
293	     * @param <T> the value type
294	     * @param n the current request amount
295	     * @param actual the target Subscriber to send events to
296	     * @param queue the queue to drain if in the post-complete state
297	     * @param state holds the request amount and the post-completed flag
298	     * @param isCancelled a supplier that returns true if the drain has been cancelled
299	     * @return true if the queue was completely drained or the drain process was cancelled
300	     */
301	    static <T> boolean postCompleteDrain(long n,
302	                                         Subscriber<? super T> actual,
303	                                         Queue<T> queue,
304	                                         AtomicLong state,
305	                                         BooleanSupplier isCancelled) {
306	
307	// TODO enable fast-path
308	//        if (n == -1 || n == Long.MAX_VALUE) {
309	//            for (;;) {
310	//                if (isCancelled.getAsBoolean()) {
311	//                    break;
312	//                }
313	//
314	//                T v = queue.poll();
315	//
316	//                if (v == null) {
317	//                    actual.onComplete();
318	//                    break;
319	//                }
320	//
321	//                actual.onNext(v);
322	//            }
323	//
324	//            return true;
325	//        }
326	
327	        long e = n & COMPLETED_MASK;
328	
329	        for (; ; ) {
330	
331	            while (e != n) {
332	                if (isCancelled(isCancelled)) {
333	                    return true;
334	                }
335	
336	                T t = queue.poll();
337	
338	                if (t == null) {
339	                    actual.onComplete();
340	                    return true;
341	                }
342	
343	                actual.onNext(t);
344	                e++;
345	            }
346	
347	            if (isCancelled(isCancelled)) {
348	                return true;
349	            }
350	
351	            if (queue.isEmpty()) {
352	                actual.onComplete();
353	                return true;
354	            }
355	
356	            n = state.get();
357	
358	            if (n == e) {
359	
360	                n = state.addAndGet(-(e & REQUESTED_MASK));
361	
362	                if ((n & REQUESTED_MASK) == 0L) {
363	                    return false;
364	                }
365	
366	                e = n & COMPLETED_MASK;
367	            }
368	        }
369	
370	    }
371	
372	    /**
373	     * Signals the completion of the main sequence and switches to post-completion replay mode.
374	     *
375	     * <p>
376	     * Don't modify the queue after calling this method!
377	     *
378	     * <p>
379	     * Post-completion backpressure handles the case when a source produces values based on
380	     * requests when it is active but more values are available even after its completion.
381	     * In this case, the onComplete() can't just emit the contents of the queue but has to
382	     * coordinate with the requested amounts. This requires two distinct modes: active and
383	     * completed. In active mode, requests flow through and the queue is not accessed but
384	     * in completed mode, requests no-longer reach the upstream but help in draining the queue.
385	     * <p>
386	     * The algorithm utilizes the most significant bit (bit 63) of a long value (AtomicLong) since
387	     * request amount only goes up to {@link Long#MAX_VALUE} (bits 0-62) and negative values aren't
388	     * allowed.
389	     *
390	     * @param <T> the value type emitted
391	     * @param actual the target Subscriber to send events to
392	     * @param queue the queue to drain if in the post-complete state
393	     * @param state holds the request amount and the post-completed flag
394	     * @param isCancelled a supplier that returns true if the drain has been cancelled
395	     */
396	    public static <T> void postComplete(Subscriber<? super T> actual,
397	                                        Queue<T> queue,
398	                                        AtomicLong state,
399	                                        BooleanSupplier isCancelled) {
400	
401	        if (queue.isEmpty()) {
402	            actual.onComplete();
403	            return;
404	        }
405	
406	        if (postCompleteDrain(state.get(), actual, queue, state, isCancelled)) {
407	            return;
408	        }
409	
410	        for (; ; ) {
411	            long r = state.get();
412	
413	            if ((r & COMPLETED_MASK) != 0L) {
414	                return;
415	            }
416	
417	            long u = r | COMPLETED_MASK;
418	            // (active, r) -> (complete, r) transition
419	            if (state.compareAndSet(r, u)) {
420	                // if the requested amount was non-zero, drain the queue
421	                if (r != 0L) {
422	                    postCompleteDrain(u, actual, queue, state, isCancelled);
423	                }
424	
425	                return;
426	            }
427	        }
428	
429	    }
430	}
